import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import axios from "axios";

function ProductList() {
  const [products, setProducts] = useState([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [category, setCategory] = useState("");

  useEffect(() => {
    // Đã sửa thành port 3000
    let apiUrl = "http://localhost:3000/products";
    
    if (category) {
      apiUrl = `http://localhost:3000/products?category=${category}`;
    }

    axios.get(apiUrl)
      .then((response) => {
        setProducts(response.data);
      })
      .catch((error) => {
        console.error("Lỗi khi lấy danh sách sản phẩm:", error);
      });
  }, [category]);

  const handleSearch = (e) => {
    e.preventDefault(); 
    
    // Đã sửa thành port 3000
    axios.get(`http://localhost:3000/search?keyword=${searchTerm}`)
      .then((response) => {
        setProducts(response.data);
      })
      .catch((error) => {
        console.error("Lỗi khi tìm kiếm:", error);
      });
  };

  return (
    <div>
      <h2>Danh sách sản phẩm</h2>

      {/* --- KHU VỰC TÌM KIẾM VÀ LỌC --- */}
      <form onSubmit={handleSearch}>
        <div>
          <input
            type="text"
            placeholder="Nhập tên sản phẩm cần tìm..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
          <button type="submit">Tìm</button>
        </div>
        
        <br />

        <div>
          <select
            value={category}
            onChange={(e) => setCategory(e.target.value)}
          >
            <option value="">Tất cả danh mục</option>
            <option value="DienThoai">Điện thoại</option>
            <option value="Laptop">Laptop</option>
          </select>
        </div>
      </form>

      <hr />

      {/* --- KHU VỰC HIỂN THỊ SẢN PHẨM --- */}
      <div>
        {products.length > 0 ? (
          <ul>
            {products.map((item) => (
              <li key={item.id}>
                <img 
                  src={item.image || "https://via.placeholder.com/200"} 
                  alt={item.name} 
                  width="200"
                />
                <div>
                  <h3>{item.name}</h3>
                  <p>{item.price} VNĐ</p>
                  
                  <Link to={`/products/${item.slug || item.id}`}>
                    <button>Xem chi tiết</button>
                  </Link>
                </div>
                <br />
              </li>
            ))}
          </ul>
        ) : (
          <p>Đang tải dữ liệu hoặc không tìm thấy sản phẩm phù hợp.</p>
        )}
      </div>
    </div>
  );
}

export default ProductList;
